def get(url, timeout=30):
    req = urllib.request.Request(url, headers=UA)
    return urllib.request.urlopen(req, timeout=timeout).read()

def yahoo_weekly(tk):
    try:
        u = 'https://query1.finance.yahoo.com/v8/finance/chart/%s?range=6mo&interval=1wk' % urllib.parse.quote(tk)
        j = json.loads(get(u))
        res = j['chart']['result'][0]
        out = []
        for t, c in zip(res['timestamp'], res['indicators']['quote'][0]['close']):
            if c is None: continue
            d = datetime.datetime.fromtimestamp(t, datetime.timezone.utc).strftime('%m-%d')
            out.append((d, round(float(c), 4)))
        return out if len(out) >= 15 else None
    except Exception as e:
        print('WARN yahoo %s: %s' % (tk, e), file=sys.stderr); return None

def fred_hyoas():
    try:
        txt = get('https://fred.stlouisfed.org/graph/fredgraph.csv?id=BAMLH0A0HYM2').decode()
        rows = []
        for line in txt.strip().split('\n')[1:]:
            p = line.split(',')
            if len(p) < 2 or p[1] in ('.', ''): continue
            rows.append((p[0][5:], int(round(float(p[1]) * 100))))
        return rows[-12:]
    except Exception as e:
        print('WARN fred: %s' % e, file=sys.stderr); return None

def imf_cpi():
    """IMF IFS 月度 CPI：美国算同比，中国序列=上年同月100(减100即同比)"""
    def fetch(ctry):
        u = ('https://dataservices.imf.org/REST/SDMX_JSON.svc/CompactData/IFS/M.%s.PCPI_IX.?startPeriod=2024-09' % ctry)
        j = json.loads(get(u))
        s = j['CompactData']['DataSet']['Series']
        obs = s['Obs'] if isinstance(s, dict) else s[0]['Obs']
        if isinstance(obs, dict): obs = [obs]
        return {o['@TIME_PERIOD']: float(o['@OBS_VALUE']) for o in obs}
    try:
        us, cn = fetch('US'), fetch('CN')
        ms = sorted(set(us) & set(cn))
        pairs = []
        for i, m in enumerate(ms):
            if i < 12: continue
            pairs.append((m[2:], round(us[m] / us[ms[i-12]] * 100 - 100, 2), round(cn[m] - 100, 2)))
        pairs = pairs[-22:]
        return {'labels': [p[0] for p in pairs], 'us': [p[1] for p in pairs], 'cn': [p[2] for p in pairs]}
    except Exception as e:
        print('WARN imf cpi: %s' % e, file=sys.stderr); return None

def imf_fxr():
    try:
        u = 'https://dataservices.imf.org/REST/SDMX_JSON.svc/CompactData/IRFCL/M.CN.RA_FX.?startPeriod=2025-01'
        j = json.loads(get(u))
        s = j['CompactData']['DataSet']['Series']
        obs = s['Obs'] if isinstance(s, dict) else s[0]['Obs']
        if isinstance(obs, dict): obs = [obs]
        rows = [(o['@TIME_PERIOD'], round(float(o['@OBS_VALUE']) / 1e12, 3)) for o in obs]
        return {'labels': [r[0] for r in rows], 'vals': [r[1] for r in rows]}
    except Exception as e:
        print('WARN imf fxr: %s' % e, file=sys.stderr); return None

def chg(vals, n, dg):
    if len(vals) <= n: return None
    return round((vals[-1] / vals[-1 - n] - 1) * 100, dg)

def dd(vals):
    return (vals[-1] / max(vals) - 1) * 100

def light(name, last, vals):
    d = dd(vals)
    table = {
     '金银比': lambda: 'g' if last < 75 else ('y' if last <= 90 else 'r'),
     '金铜比': lambda: 'g' if last < 660 else ('y' if last <= 700 else 'r'),
     'MOVE 利率波动率': lambda: 'g' if last < 90 else ('y' if last <= 120 else 'r'),
     'HYG 高收益债ETF': lambda: 'g' if d > -3 else ('y' if d > -8 else 'r'),
     'VXX 波动率期货ETN': lambda: 'g' if last < 20 else ('y' if last <= 35 else 'r'),
     '标普500': lambda: 'g' if d > -5 else ('y' if d > -15 else 'r'),
     '纳斯达克100综指': lambda: 'g' if d > -5 else ('y' if d > -15 else 'r'),
     'VIX恐慌指数': lambda: 'g' if last < 20 else ('y' if last <= 30 else 'r'),
     '黄金': lambda: 'g' if d > -10 else ('y' if d > -20 else 'r'),
     '白银': lambda: 'g' if d > -10 else ('y' if d > -20 else 'r'),
     '铜': lambda: 'g' if d > -8 else ('y' if d > -15 else 'r'),
     'WTI原油': lambda: 'g' if d > -8 else ('y' if d > -18 else 'r'),
     '美债10Y收益率': lambda: 'g' if last < 4.5 else ('y' if last <= 5.2 else 'r'),
     '美元指数': lambda: 'g' if last < 100 else ('y' if last <= 105 else 'r'),
     'USD/CNY 在岸': lambda: 'g' if last < 6.8 else ('y' if last <= 7.0 else 'r'),
    }
    return table.get(name, lambda: 'y')()

def build_card(base, fetched):
    c = dict(base)
    name = c['name']
    src = None
    if name in RATIO_OF:
        a, b = RATIO_OF[name]
        fa, fb = fetched.get(TICKERS[a]), fetched.get(TICKERS[b])
        if fa and fb and len(fa) == len(fb):
            src = [(fa[i][0], round(fa[i][1] / fb[i][1], 4)) for i in range(len(fa))]
    else:
        src = fetched.get(TICKERS.get(name))
    if src:
        c['dates'] = [d for d, _ in src]
        c['vals'] = [v for _, v in src]
    vals = c['vals']
    dg = c.get('cdigits', c['digits'])
    c['last'] = round(vals[-1], c['digits'])
    c['w1'] = chg(vals, 1, dg); c['m1'] = chg(vals, 4, dg)
    c['m3'] = chg(vals, 13, dg)
    c['m6'] = chg(vals, 26, dg) if len(vals) > 26 else round((vals[-1] / vals[0] - 1) * 100, dg)
    c['light'] = light(name, vals[-1], vals)
    return c

def main():
    fetched = {}
    ok = 0
    all_tks = dict(TICKERS)
    for name, tk in list(all_tks.items()) + list(RATE_TICKERS.items()):
        if tk in fetched: continue
        r = yahoo_weekly(tk)
        if r:
            fetched[tk] = r
            if tk in TICKERS.values(): ok += 1
    print('yahoo ok: %d/%d' % (ok, len(TICKERS)))
    if ok < MIN_OK:
        print('成功标的过少（<%d），保留旧 data.json' % MIN_OK); sys.exit(0)

    cards = [build_card(c, fetched) for c in CARDS0]
    sig = [build_card(s, fetched) for s in SIG0]
    rates = None
    if all(tk in fetched for tk in RATE_TICKERS.values()):
        ref = fetched['^TNX']
        rates = {'labels': [d for d, _ in ref]}
        for k, tk in RATE_TICKERS.items():
            rates[k] = [v for _, v in fetched[tk]]
    hy = fred_hyoas()
    hyoas = ({'vals': [v for _, v in hy], 'dates': [d for d, _ in hy],
              'last': hy[-1][1], 'w1': hy[-1][1] - hy[-2][1]} if hy else HYOAS0)
    data = {'meta': {'updated': datetime.datetime.now(datetime.timezone.utc).strftime('%Y-%m-%d %H:%M UTC'),
                     'yahoo_ok': ok},
            'cards': cards, 'sig': sig,
            'rates': rates or RATES0,
            'cpi': imf_cpi() or CPI0, 'fxr': imf_fxr() or FXR0, 'hyoas': hyoas}
    with open('data.json', 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, separators=(',', ':'))
    print('data.json written, %d bytes' % os.path.getsize('data.json'))

if __name__ == '__main__':
    main()
